66	
67	    ngOnInit(): void {
68	        this.featureToggleSubscription = this.featureToggleService.getFeatureToggleActive(FeatureToggle.TutorSuggestions).subscribe((active) => {
69	            if (active) {
70	                this.subscribeToIrisActivation();
71	
72	                if (!this.profileService.isProfileActive(PROFILE_IRIS)) {
73	                    return;
74	                }
75	                const course = this.course();
76	                const post = this.post();
77	                this.isAtLeastTutor = this.accountService.isAtLeastTutorInCourse(course);
78	                if (!this.isAtLeastTutor || post?.resolved) {
79	                    return;
80	                }
81	                if (course?.id && post) {
82	                    this.irisSettingsSubscription = this.irisSettingsService.getCombinedCourseSettings(course.id).subscribe((settings) => {
83	                        this.irisEnabled = !!settings?.irisTutorSuggestionSettings?.enabled;
84	                        if (this.irisEnabled) {
85	                            this.chatService.switchTo(ChatServiceMode.TUTOR_SUGGESTION, post.id);
86	                            this.fetchMessages();
87	                        }
88	                    });
89	                }
90	            } else {
91	                this.irisEnabled = false;
92	            }
93	        });
94	    }
95	
96	    ngOnChanges(): void {
97	        if (this.irisEnabled) {
98	            const post = this.post();
99	            if (post) {
100	                this.chatService.switchTo(ChatServiceMode.TUTOR_SUGGESTION, post.id);
101	                this.messagesSubscription?.unsubscribe();
102	
103	                this.subscribeToIrisActivation();
104	            }
105	            this.fetchMessages();
106	        }
107	    }
108	
109	    ngOnDestroy() {
110	        this.messagesSubscription?.unsubscribe();
111	        this.irisSettingsSubscription?.unsubscribe();
112	        this.tutorSuggestionSubscription?.unsubscribe();
113	        this.stagesSubscription?.unsubscribe();
114	        this.errorSubscription?.unsubscribe();
115	        this.irisActivationSubscription?.unsubscribe();
116	        this.featureToggleSubscription?.unsubscribe();
117	    }
