119	    /**
120	     * Requests a tutor suggestion from the chat service
121	     * This method is called when the component is initialized or when the post changes
122	     */
123	    requestSuggestion(): void {
124	        const post = this.post();
125	        if (!post) {
126	            return;
127	        }
128	
129	        const waitForSessionAndMessages$ = this.chatService.currentSessionId().pipe(
130	            filter((id): id is number => !!id),
131	            take(1),
132	            switchMap(() =>
133	                this.chatService.currentMessages().pipe(
134	                    skip(1), // The initial message is not relevant as the system is sending an empty array first
135	                    take(1),
136	                    catchError((err) => {
137	                        this.error = IrisErrorMessageKey.SESSION_LOAD_FAILED;
138	                        return of([]);
139	                    }),
140	                ),
141	            ),
142	        );
143	
144	        this.tutorSuggestionSubscription = waitForSessionAndMessages$.subscribe((messages) => {
145	            const lastMessage = messages[messages.length - 1];
146	            const shouldRequest = messages.length === 0 || !(lastMessage?.sender === IrisSender.LLM || lastMessage?.sender === IrisSender.ARTIFACT);
147	            if (shouldRequest) {
148	                this.chatService
149	                    .requestTutorSuggestion()
150	                    .pipe(
151	                        catchError((err) => {
152	                            this.error = IrisErrorMessageKey.SEND_MESSAGE_FAILED;
153	                            return of(undefined);
154	                        }),
155	                    )
156	                    .subscribe();
157	            }
158	        });
159	    }
160	
161	    /**
162	     * Fetches the messages from the chat service and updates the suggestion if necessary
163	     */
164	    private fetchMessages(): void {
165	        this.messagesSubscription = this.chatService.currentMessages().subscribe((messages) => {
